export const studioJavaScript = String.raw`
"use strict";
const $ = id => document.getElementById(id);
const state = { token:sessionStorage.getItem('frameos.studio.token')||'', project:null, assets:[], selectedId:null, selectedAsset:null, selectedTrack:null, checked:new Set(), urls:new Map(), durations:new Map(), playhead:0, zoom:16, playing:false, sourceMode:false, mediaGeneration:0, busy:false, running:false, stop:false, plan:null, capabilities:[] };
const uid=()=>crypto.randomUUID();
async function showFrame(){const pending=state.pendingFrame=(state.pendingFrame||0)+1;state.framePending=true;try{await loadFrame();}finally{if(state.pendingFrame===pending)state.framePending=false;}}
state.thumbnails=new Map();
async function thumbnail(asset){if(asset.kind!=='video'||state.thumbnails.has(asset.id))return;try{const url=await mediaUrl(asset);const projectId=state.project.projectId;const video=document.createElement('video');video.muted=true;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{cleanup();reject(Error('Thumbnail timeout'));},8000);const cleanup=()=>{clearTimeout(timer);video.onloadedmetadata=null;video.onseeked=null;video.onerror=null;video.removeAttribute('src');video.load();};video.onloadedmetadata=()=>{video.currentTime=Math.min(.3,video.duration/2);};video.onseeked=()=>{const canvas=document.createElement('canvas');canvas.width=240;canvas.height=135;canvas.getContext('2d').drawImage(video,0,0,240,135);if(state.project?.projectId===projectId)state.thumbnails.set(asset.id,canvas.toDataURL('image/jpeg',.7));cleanup();resolve();};video.onerror=()=>{cleanup();reject(Error('Thumbnail unavailable'));};video.src=url;});}catch{/* Thumbnails are optional; source preview errors remain visible. */}}
const seconds=t=>t&&t.rate?Number(t.value)*t.rate.denominator/t.rate.numerator:0;
const seq=()=>state.project&&state.project.sequences[state.project.settings.defaultSequenceId];
const fps=()=>seq()?seq().format.frameRate.numerator/seq().format.frameRate.denominator:30;
const snap=n=>Math.max(0,Math.round(Number(n)*fps())/fps());
const time=n=>({value:Math.round(Math.max(0,Number(n))*fps()),rate:seq()?seq().format.frameRate:{numerator:30,denominator:1}});
const range=(s,d)=>({start:time(s),duration:time(Math.max(1/fps(),d))});
const end=item=>seconds(item.timelineRange.start)+seconds(item.timelineRange.duration);
const trackEnd=t=>Math.max(0,...t.items.map(end));
const duration=()=>seq()?Math.max(0,...seq().tracks.filter(t=>t.enabled).map(trackEnd)):0;
const clock=n=>{n=Math.max(0,n||0);return String(Math.floor(n/60)).padStart(2,'0')+':'+(n%60).toFixed(2).padStart(5,'0');};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message,error=false){$('toast').textContent=message;$('toast').className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').className='',7000);}
function guard(fn){return (...args)=>Promise.resolve().then(()=>fn(...args)).catch(e=>toast(e.message||String(e),true));}
function bind(id,fn){$(id).addEventListener('click',guard(fn));}
async function api(method,path,body){if(!state.token)throw Error('Connect your local daemon first.');const r=await fetch('/api/v1'+path,{method,headers:{authorization:'Bearer '+state.token,...(body===undefined?{}:{'content-type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)})});const e=await r.json();if(!r.ok||e.error)throw Error(e.error?.message||'Request failed: '+r.status);return e.data;}
function needProject(){if(!state.project)throw Error('Create or open a project first.');}
function selection(){const s=seq();if(s)for(const track of s.tracks){const item=track.items.find(i=>i.id===state.selectedId);if(item)return {track,item};}return null;}
function needClip(){const s=selection();if(!s||s.item.type!=='clip')throw Error('Select a video or audio clip on the timeline.');if(s.track.locked||s.item.locked)throw Error('Unlock this clip’s track first.');return s;}
function operation(type,args,targetId,agent=false){return {operationId:uid(),type,arguments:args,preconditions:[],provenance:{actorType:agent?'agent':'human',actorId:agent?'studio.montage-assistant':'studio.editor'},...(targetId?{targetId}:{})};}
async function commit(operations,agent=false){needProject();if(state.busy||state.running&&!agent)throw Error('Wait for the current edit to finish.');state.busy=true;$('save-state').textContent='Saving…';try{const r=await api('POST','/transactions',{projectId:state.project.projectId,baseRevision:state.project.revision,idempotencyKey:'studio-'+uid(),mode:'commit',operations});await reload();return r;}finally{state.busy=false;$('save-state').textContent='Saved locally';}}
function clearMedia(){for(const entry of state.urls.values())entry.then(url=>URL.revokeObjectURL(url)).catch(()=>{});state.urls.clear();state.durations.clear();state.thumbnails?.clear();}
async function openProject(id){if(state.running||state.busy)throw Error('Stop the current action before switching projects.');pause();state.mediaGeneration++;clearMedia();state.project=await api('GET','/projects/'+id);state.assets=await api('GET','/projects/'+id+'/assets');state.selectedId=null;state.selectedAsset=null;state.checked.clear();state.plan=null;$('plan').replaceChildren();$('approve').hidden=true;state.sourceMode=false;state.playhead=0;renderMedia();renderTimeline();fillProperties();await showFrame();}
async function reload(){state.project=await api('GET','/projects/'+state.project.projectId);state.assets=await api('GET','/projects/'+state.project.projectId+'/assets');renderMedia();renderTimeline();fillProperties();if(!state.playing)await showFrame();}
async function connect(){state.token=$('token').value.trim();sessionStorage.setItem('frameos.studio.token',state.token);const [projects,caps]=await Promise.all([api('GET','/projects'),api('GET','/capabilities')]);state.capabilities=caps;$('projects').innerHTML='<option value="">Choose a project</option>'+projects.map(p=>'<option value="'+escape(p.projectId)+'">'+escape(p.name)+'</option>').join('');$('connection-panel').hidden=true;$('connection').textContent='● Connected';$('save-state').textContent='Saved locally';if(projects.length){$('projects').value=projects[0].projectId;await openProject(projects[0].projectId);}await refreshJobs();}
function showPanel(name){document.querySelectorAll('.library-panel').forEach(p=>p.hidden=p.id!=='panel-'+name);document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));}
function showInspector(agent){document.querySelector('.inspector').scrollTop=0;$('agent').hidden=!agent;$('properties').hidden=agent;$('agent-tab').classList.toggle('active',agent);$('properties-tab').classList.toggle('active',!agent);}
function renderMedia(){const q=$('media-filter').value.toLowerCase();$('asset-count').textContent=state.assets.length;$('media-list').innerHTML=state.assets.filter(a=>a.name.toLowerCase().includes(q)).map(a=>'<article class="media-card '+(state.selectedAsset===a.id?'selected':'')+'" data-asset="'+a.id+'" draggable="true" tabindex="0" aria-label="Preview '+escape(a.name)+'"><div class="media-thumb">'+(state.thumbnails?.has(a.id)?'<img src="'+state.thumbnails.get(a.id)+'" alt="">':a.kind==='audio'?'♫':a.kind==='image'?'▧':'▶')+'</div><label><input type="checkbox" data-check="'+a.id+'" aria-label="Include '+escape(a.name)+' in montage" '+(state.checked.has(a.id)?'checked':'')+'></label><header><b>'+escape(a.name)+'</b><button data-add="'+a.id+'" title="Add to timeline">＋</button></header><small>'+escape(a.kind)+' · '+(state.durations.has(a.id)?clock(state.durations.get(a.id)):a.duration?clock(seconds(a.duration)):'Preview to load duration')+'</small></article>').join('')||'<p class="hint">Your imported media will appear here.</p>';}
async function mediaUrl(asset){if(!state.urls.has(asset.id)){const projectId=state.project.projectId;const pending=(async()=>{const r=await fetch('/api/v1/projects/'+projectId+'/assets/'+asset.id+'/content',{headers:{authorization:'Bearer '+state.token}});if(!r.ok)throw Error('Unable to load '+asset.name+' ('+r.status+').');return URL.createObjectURL(await r.blob());})();state.urls.set(asset.id,pending);pending.catch(()=>{if(state.urls.get(asset.id)===pending)state.urls.delete(asset.id);});}return state.urls.get(asset.id);}
async function mediaDuration(asset){if(state.durations.has(asset.id))return state.durations.get(asset.id);if(asset.duration&&seconds(asset.duration)>0)return seconds(asset.duration);if(asset.kind==='image')return 5;const url=await mediaUrl(asset);const d=await new Promise((resolve,reject)=>{const m=document.createElement(asset.kind==='audio'?'audio':'video');const timer=setTimeout(()=>{m.removeAttribute('src');m.load();reject(Error('Could not read the duration of '+asset.name));},20000);m.onloadedmetadata=()=>{clearTimeout(timer);const d=m.duration;m.removeAttribute('src');m.load();Number.isFinite(d)&&d>0?resolve(d):reject(Error('This media has no finite duration.'));};m.onerror=()=>{clearTimeout(timer);reject(Error('This browser cannot decode '+asset.name));};m.src=url;});state.durations.set(asset.id,d);return d;}
async function selectMedia(id){if(state.running)throw Error('Stop the assistant before changing the preview.');pause();state.selectedAsset=id;state.sourceMode=true;state.sourceTime=0;renderMedia();await showFrame();const a=state.assets.find(a=>a.id===id);if(a){await mediaDuration(a);await thumbnail(a);renderMedia();}}
function pictureAt(at){if(!seq())return null;if(at===duration()&&at>0)at-=1/fps();const tracks=[...seq().tracks].filter(t=>t.enabled&&t.kind==='video').sort((a,b)=>b.order-a.order);for(const track of tracks){const item=track.items.find(i=>i.enabled&&i.type==='clip'&&at>=seconds(i.timelineRange.start)&&at<end(i));if(item)return {track,item};}return null;}
function sourceAt(item,at){const offset=at-seconds(item.timelineRange.start);return seconds(item.sourceRange.start)+offset*(seconds(item.sourceRange.duration)/seconds(item.timelineRange.duration));}
async function loadFrame(){const generation=++state.mediaGeneration;let item=null,track=null,asset=null,at=0;if(state.sourceMode){asset=state.assets.find(a=>a.id===state.selectedAsset);at=state.sourceTime||0;}else{const pic=pictureAt(state.playhead);item=pic?.item;track=pic?.track;asset=item&&state.assets.find(a=>a.id===item.assetId);if(item)at=sourceAt(item,state.playhead);}
 $('monitor-label').textContent=state.sourceMode?'Source · '+(asset?.name||''):'Timeline preview';$('title-overlay').textContent=state.sourceMode?'':(seq()?.tracks.filter(t=>t.enabled).flatMap(t=>t.items).filter(i=>i.type==='title'&&i.enabled&&state.playhead>=seconds(i.timelineRange.start)&&state.playhead<end(i)).map(i=>i.text).join('\n')||'');
 const video=$('preview');if(!asset){video.pause();video.hidden=true;$('image-preview').hidden=true;$('preview-empty').hidden=!!$('title-overlay').textContent;return;}const url=await mediaUrl(asset);if(generation!==state.mediaGeneration)return;$('preview-empty').hidden=true;
 if(asset.kind==='image'){video.pause();video.hidden=true;$('image-preview').src=url;$('image-preview').hidden=false;return;}$('image-preview').hidden=true;video.hidden=false;
 if(video.getAttribute('src')!==url){video.pause();state.cancelPreviewLoad?.();state.previewLoad=new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{cleanup();reject(Error('Preview loading timed out.'));},20000);const cleanup=()=>{clearTimeout(timeout);video.removeEventListener('loadedmetadata',ok);video.removeEventListener('error',fail);state.cancelPreviewLoad=null;};const ok=()=>{cleanup();resolve();};const fail=()=>{cleanup();reject(Error('Video format could not be decoded.'));};state.cancelPreviewLoad=ok;video.addEventListener('loadedmetadata',ok);video.addEventListener('error',fail);video.src=url;});}if(video.readyState<1&&state.previewLoad)await state.previewLoad;if(generation!==state.mediaGeneration)return;
 const tr=item?.transform||{};video.style.transform='scale('+(tr.scaleX??1)+','+(tr.scaleY??1)+') rotate('+(tr.rotation||0)+'deg)';video.style.opacity=String(tr.opacity??1);video.volume=Math.min(1,Math.pow(10,(item?.audio?.gainDb||0)/20));video.muted=!!(track?.muted||item?.audio?.muted);video.playbackRate=item?Math.max(.0625,Math.min(16,seconds(item.sourceRange.duration)/seconds(item.timelineRange.duration))):1;
 if(Math.abs(video.currentTime-at)>.08)video.currentTime=Math.max(0,Math.min(at,Number.isFinite(video.duration)?video.duration:at));if(state.playing)await video.play();}
function updateHead(){const total=duration();$('timecode').textContent=clock(state.sourceMode?state.sourceTime:state.playhead);$('duration').textContent=clock(state.sourceMode?(state.durations.get(state.selectedAsset)||0):total);$('playhead').style.left=(100+state.playhead*state.zoom)+'px';$('ruler').setAttribute('aria-valuenow',String(state.playhead));$('ruler').setAttribute('aria-valuemax',String(Math.max(total,30)));}
function seek(value){pause();state.sourceMode=false;state.playhead=snap(Math.max(0,Math.min(Math.max(duration(),30),value)));updateHead();guard(showFrame)();}
function pause(){state.playing=false;$('preview').pause();$('play').textContent='▶';cancelAnimationFrame(state.raf);}
async function play(){if(state.playing){pause();return;}needProject();if(!state.sourceMode&&duration()===0)throw Error('Add media to the timeline first.');if(!state.sourceMode&&state.playhead>=duration())state.playhead=0;state.playing=true;$('play').textContent='Ⅱ';try{await showFrame();}catch(e){pause();throw e;}state.lastTick=performance.now();const tick=now=>{if(!state.playing)return;if(state.framePending||(!$('preview').hidden&&$('preview').readyState<3)){state.lastTick=now;state.raf=requestAnimationFrame(tick);return;}const delta=Math.min(.1,(now-state.lastTick)/1000);state.lastTick=now;if(state.sourceMode){state.sourceTime=$('preview').currentTime;if($('preview').ended){pause();return;}}else{const previous=pictureAt(state.playhead);state.playhead=Math.min(duration(),state.playhead+delta);const next=pictureAt(state.playhead);if(previous?.item.id!==next?.item.id)guard(showFrame)();else if(next){const expected=sourceAt(next.item,state.playhead);if(Math.abs($('preview').currentTime-expected)>.3)$('preview').currentTime=expected;}$('title-overlay').textContent=seq().tracks.filter(t=>t.enabled).flatMap(t=>t.items).filter(i=>i.type==='title'&&i.enabled&&state.playhead>=seconds(i.timelineRange.start)&&state.playhead<end(i)).map(i=>i.text).join('\n');if(state.playhead>=duration())pause();}updateHead();if(state.playing)state.raf=requestAnimationFrame(tick);};state.raf=requestAnimationFrame(tick);}
function trackObject(kind,name){return {id:uid(),name:name||(kind==='audio'?'Audio':'Video')+' '+((seq()?.tracks.length||0)+1),kind,order:Math.max(0,...(seq()?.tracks.map(t=>t.order)||[]))+1,enabled:true,locked:false,muted:false,syncLocked:true,items:[],effects:[],metadata:{}};}
function clipObject(asset,start,source,d){return {id:uid(),type:'clip',name:asset.name,assetId:asset.id,timelineRange:range(start,d),sourceRange:range(source,d),transform:{},audio:{},enabled:true,locked:false,metadata:{},timeMap:[],effects:[],links:[],semanticMetadata:{}};}
async function addAsset(id,trackId,start){needProject();const a=state.assets.find(a=>a.id===id);if(!a)throw Error('Media no longer exists.');const kind=a.kind==='audio'?'audio':'video';let track=seq().tracks.find(t=>t.id===trackId)||seq().tracks.find(t=>t.kind===kind&&t.enabled&&!t.locked);const ops=[];if(!track){track=trackObject(kind);ops.push(operation('track.add',{sequenceId:seq().id,track}));}if(track.locked)throw Error('Unlock the destination track first.');if(track.kind!==kind)throw Error('Drop this media on a '+kind+' track.');const d=await mediaDuration(a),clip=clipObject(a,start===undefined?trackEnd(track):snap(start),0,d);ops.push(operation('item.add',{sequenceId:seq().id,trackId:track.id,item:clip}));await commit(ops);state.selectedId=clip.id;state.selectedTrack=track.id;state.sourceMode=false;seek(seconds(clip.timelineRange.start));renderTimeline();fillProperties();}
function renderTimeline(){const s=seq();const width=Math.max($('timeline-scroll').clientWidth-100,Math.max(30,duration()+10)*state.zoom);$('timeline-content').style.width=(width+100)+'px';$('ruler').style.width=width+'px';$('ruler').replaceChildren();const step=state.zoom<10?10:state.zoom<30?5:1;for(let t=0;t*state.zoom<=width;t+=step){const tick=document.createElement('span');tick.className='tick';tick.style.left=t*state.zoom+'px';tick.textContent=clock(t);$('ruler').append(tick);}for(const marker of s?.markers||[]){const m=document.createElement('span');m.className='marker';m.textContent='◆';m.title=marker.name;m.style.left=seconds(marker.range.start)*state.zoom+'px';$('ruler').append(m);}
 $('tracks').innerHTML=(s?.tracks||[]).slice().sort((a,b)=>b.order-a.order).map(t=>'<div class="track '+(!t.enabled?'disabled':'')+'"><div class="track-label"><b>'+escape(t.name)+'</b><div><button data-lock="'+t.id+'" title="'+(t.locked?'Unlock':'Lock')+' track">'+(t.locked?'🔒':'○')+'</button><button data-mute="'+t.id+'" title="'+(t.muted?'Unmute':'Mute')+' track">'+(t.muted?'M':'♫')+'</button><button data-enable="'+t.id+'" title="Enable / disable track">'+(t.enabled?'●':'◌')+'</button></div></div><div class="lane" data-track="'+t.id+'">'+t.items.map(i=>'<div role="button" tabindex="0" aria-label="'+escape(i.name)+'" class="timeline-clip '+(t.kind==='audio'?'audio':i.type)+' '+(state.selectedId===i.id?'selected':'')+'" data-item="'+i.id+'"><b>'+escape(i.name)+'</b><small>'+clock(seconds(i.timelineRange.duration))+'</small>'+(i.type==='clip'?'<span class="trim left" data-trim="left" title="Trim start"></span><span class="trim right" data-trim="right" title="Trim end"></span>':'')+'</div>').join('')+'</div></div>').join('');
 document.querySelectorAll('[data-item]').forEach(node=>{const t=s.tracks.find(t=>t.id===node.closest('[data-track]').dataset.track);const i=t.items.find(i=>i.id===node.dataset.item);node.style.left=seconds(i.timelineRange.start)*state.zoom+'px';node.style.width=seconds(i.timelineRange.duration)*state.zoom+'px';});$('revision').textContent=state.project?'Revision '+state.project.revision:'No project';if(s)$('format').textContent=s.format.width+' × '+s.format.height;updateHead();}
function fillProperties(){const x=selection();$('selection-name').textContent=x?.item.name||'No clip selected';$('clip-properties').disabled=!x||x.item.type!=='clip'||x.track.locked;if(!x||x.item.type!=='clip')return;const i=x.item;$('clip-start').value=seconds(i.timelineRange.start).toFixed(3);$('source-in').value=seconds(i.sourceRange.start).toFixed(3);$('clip-duration').value=seconds(i.sourceRange.duration).toFixed(3);$('scale').value=i.transform.scaleX??1;$('rotation').value=i.transform.rotation||0;$('opacity').value=i.transform.opacity??1;$('gain').value=i.audio.gainDb||0;}
function selectItem(id){state.selectedId=id;state.selectedTrack=selection()?.track.id;state.sourceMode=false;document.querySelectorAll('[data-item]').forEach(n=>n.classList.toggle('selected',n.dataset.item===id));fillProperties();showInspector(false);}
async function split(){const {track,item}=needClip(),at=snap(state.playhead);if(at<=seconds(item.timelineRange.start)||at>=end(item))throw Error('Click the ruler inside the selected clip, then Split.');pause();await commit([operation('clip.split',{sequenceId:seq().id,trackId:track.id,at:time(at),rightClipId:uid()},item.id)]);}
async function trimTo(item,track,start,source,d){if(item.timeMap.length)throw Error('Use the advanced workbench to trim retimed clips.');const asset=state.assets.find(a=>a.id===item.assetId);const max=await mediaDuration(asset);if(source<0||d<1/fps()||source+d>max+1/fps())throw Error('The trim must stay within the source media.');await commit([operation('clip.trim',{sequenceId:seq().id,trackId:track.id,sourceRange:range(source,d)},item.id),operation('clip.move',{sequenceId:seq().id,fromTrackId:track.id,toTrackId:track.id,timelineStart:time(start)},item.id)]);}
let pointer=null;
$('ruler').addEventListener('pointerdown',event=>{if(state.running||event.button!==0)return;const rect=$('ruler').getBoundingClientRect();pointer={mode:'seek',left:rect.left};$('ruler').setPointerCapture(event.pointerId);seek((event.clientX-rect.left)/state.zoom);});
$('tracks').addEventListener('pointerdown',event=>{if(state.running||state.busy||event.button!==0||event.target.closest('button'))return;const node=event.target.closest('[data-item]'),lane=event.target.closest('[data-track]');if(!lane)return;if(!node){pointer={mode:'seek',left:lane.getBoundingClientRect().left};seek((event.clientX-pointer.left)/state.zoom);return;}selectItem(node.dataset.item);const {item,track}=selection();if(track.locked||item.locked||item.type!=='clip')return;pause();event.preventDefault();pointer={mode:event.target.dataset.trim||'move',node,item,track,x:event.clientX,start:seconds(item.timelineRange.start),source:seconds(item.sourceRange.start),duration:seconds(item.sourceRange.duration),moved:false};node.setPointerCapture(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!pointer)return;if(pointer.mode==='seek'){seek((event.clientX-pointer.left)/state.zoom);return;}const p=pointer,delta=(event.clientX-p.x)/state.zoom;p.moved=p.moved||Math.abs(event.clientX-p.x)>3;if(p.mode==='move')p.node.style.left=snap(p.start+delta)*state.zoom+'px';else if(p.mode==='right')p.node.style.width=Math.max(1/fps(),p.duration+delta)*state.zoom+'px';else{const d=Math.max(-p.source,-p.start,Math.min(p.duration-1/fps(),delta));p.node.style.left=(p.start+d)*state.zoom+'px';p.node.style.width=(p.duration-d)*state.zoom+'px';}});
document.addEventListener('pointerup',guard(async event=>{const p=pointer;pointer=null;if(!p||p.mode==='seek'||!p.moved)return;const delta=(event.clientX-p.x)/state.zoom;try{if(p.mode==='move'){const lane=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-track]');await commit([operation('clip.move',{sequenceId:seq().id,fromTrackId:p.track.id,toTrackId:lane?.dataset.track||p.track.id,timelineStart:time(snap(p.start+delta))},p.item.id)]);}else if(p.mode==='right')await trimTo(p.item,p.track,p.start,p.source,snap(Math.max(1/fps(),p.duration+delta)));else{const d=snap(p.source+Math.max(-p.source,-p.start,Math.min(p.duration-1/fps(),delta)))-p.source;await trimTo(p.item,p.track,p.start+d,p.source+d,p.duration-d);}}finally{renderTimeline();}}));
document.addEventListener('pointercancel',()=>{pointer=null;renderTimeline();});
$('tracks').addEventListener('dragover',event=>{const lane=event.target.closest('[data-track]');if(lane){event.preventDefault();lane.classList.add('drag-over');}});
$('tracks').addEventListener('dragleave',event=>event.target.closest('[data-track]')?.classList.remove('drag-over'));
$('tracks').addEventListener('drop',guard(async event=>{event.preventDefault();const lane=event.target.closest('[data-track]');if(!lane)return;lane.classList.remove('drag-over');await addAsset(event.dataTransfer.getData('application/frameos-asset'),lane.dataset.track,(event.clientX-lane.getBoundingClientRect().left)/state.zoom);}));
$('tracks').addEventListener('click',guard(async event=>{const b=event.target.closest('button');if(!b)return;const id=b.dataset.lock||b.dataset.mute||b.dataset.enable,t=seq().tracks.find(t=>t.id===id);if(!t)return;const type=b.dataset.lock?(t.locked?'track.unlock':'track.lock'):b.dataset.mute?(t.muted?'track.unmute':'track.mute'):'track.update';await commit([operation(type,{sequenceId:seq().id,...(b.dataset.enable?{values:{enabled:!t.enabled}}:{})},id)]);}));
$('media-list').addEventListener('click',guard(async event=>{if(event.target.closest('input'))return;const add=event.target.closest('[data-add]');if(add){await addAsset(add.dataset.add);return;}const card=event.target.closest('[data-asset]');if(card)await selectMedia(card.dataset.asset);}));
$('media-list').addEventListener('change',event=>{const id=event.target.dataset.check;if(id){event.target.checked?state.checked.add(id):state.checked.delete(id);}});
$('media-list').addEventListener('dblclick',guard(async event=>{if(event.target.closest('button,input'))return;const card=event.target.closest('[data-asset]');if(card)await addAsset(card.dataset.asset);}));
$('media-list').addEventListener('dragstart',event=>{const card=event.target.closest('[data-asset]');if(card){event.dataTransfer.setData('application/frameos-asset',card.dataset.asset);event.dataTransfer.effectAllowed='copy';}});
$('media-list').addEventListener('keydown',guard(async event=>{if(event.key==='Enter'&&event.target.dataset.asset)await selectMedia(event.target.dataset.asset);}));
$('tracks').addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.dataset.item)selectItem(event.target.dataset.item);});
async function importFiles(){needProject();if(state.running||state.busy)throw Error('Wait for the current edit to finish.');state.busy=true;try{for(const file of $('files').files){$('save-state').textContent='Importing '+file.name+'…';const form=new FormData();form.append('file',file);const kind=file.type.startsWith('audio/')?'audio':file.type.startsWith('image/')?'image':'video';const r=await fetch('/api/v1/assets/uploads?projectId='+state.project.projectId+'&baseRevision='+state.project.revision+'&kind='+kind,{method:'POST',headers:{authorization:'Bearer '+state.token},body:form});const e=await r.json();if(!r.ok||e.error)throw Error(e.error?.message||'Import failed.');await reload();state.checked.add(e.data.asset.id);state.selectedAsset=e.data.asset.id;state.sourceMode=true;await showFrame();await mediaDuration(e.data.asset);await thumbnail(e.data.asset);renderMedia();}toast('Media imported. Drag clips to the timeline or open Edit assistant.');}finally{state.busy=false;$('files').value='';$('save-state').textContent='Saved locally';}}
async function refreshJobs(){if(!state.project)return;const jobs=await api('GET','/jobs?projectId='+state.project.projectId);$('jobs').innerHTML=jobs.slice(0,15).map(j=>'<article class="job '+escape(j.status)+'"><b>'+escape(j.kind)+' · '+escape(j.status)+'</b><br><small>'+Math.round((j.progress||0)*100)+'% '+escape(j.error?.message||'')+'</small></article>').join('')||'<p class="hint">No jobs yet.</p>';}
async function analyze(asset){return api('POST','/projects/'+state.project.projectId+'/assets/'+asset.id+'/analysis',{projectId:state.project.projectId,assetId:asset.id,analyzers:['google.vertex.gemini.video'],parameters:{}});}
async function searchAsset(asset,query=''){return api('POST','/assets/search',{projectId:state.project.projectId,assetIds:[asset.id],query,types:['visual_semantic','scenes','shots','quality'],mode:'lexical',limit:500});}
function log(message){const li=document.createElement('li');li.textContent=message;$('agent-log').append(li);}
async function waitForAnalysis(job){let current=job;for(let i=0;i<600;i++){if(state.stop)throw Error('Stopped. No montage edits were applied.');if(current.status==='completed')return;if(['failed','cancelled'].includes(current.status))throw Error(current.error?.message||'Video analysis failed.');await new Promise(r=>setTimeout(r,1500));current=await api('GET','/jobs/'+job.id);}throw Error('Analysis is still running. Check Activity and propose again when it finishes.');}
async function proposeMontage(){
 needProject();if(state.running||state.busy)throw Error('Wait for the current operation.');
 const brief=$('brief').value.trim();if(!brief)throw Error('Describe how you want the video edited.');
 const assets=state.assets.filter(a=>state.checked.has(a.id));if(assets.length>20)throw Error('Select up to 20 media files.');
 state.running=true;state.stop=false;state.plan=null;$('approve').hidden=true;$('stop').hidden=false;$('propose').disabled=true;$('agent-log').replaceChildren();$('plan').textContent='Preparing your AI editing request…';
 try{
 const durations={};const used=new Set([...assets.map(a=>a.id),...seq().tracks.flatMap(t=>t.items.filter(i=>i.type==='clip').map(i=>i.assetId))]);
 for(const id of used){if(state.stop)throw Error('Stopped. No timeline edits were applied.');const asset=state.assets.find(a=>a.id===id);durations[id]=await mediaDuration(asset);}
 if($('analyze-before-plan').checked){const videos=assets.length?assets:state.assets.filter(a=>used.has(a.id));for(const asset of videos.filter(a=>a.kind==='video')){if(state.stop)throw Error('Stopped. No edits were applied.');let results=await searchAsset(asset);if(!results.some(r=>r.range)){log('Analyzing '+asset.name+' with Gemini…');await waitForAnalysis(await analyze(asset));}}}
 if(state.stop)throw Error('Stopped. No edits were applied.');
 log('Gemini is interpreting your editing brief…');
 await reload();const revision=state.project.revision;
 const proposal=await api('POST','/studio/ai/plan',{projectId:state.project.projectId,baseRevision:revision,brief,assetIds:assets.map(a=>a.id),selectedItemId:state.selectedId,playhead:state.playhead,durations,secondsPerClip:Number($('montage-length').value)});
 if(state.stop)throw Error('Stopped. The returned plan was discarded; no edits were applied.');
 if(proposal.clarification){$('plan').textContent=proposal.clarification;log('AI needs clarification. Update your brief and try again.');return;}
 state.plan={...proposal,steps:proposal.steps.map(s=>({...s,target:s.assetId?'[data-asset="'+s.assetId+'"]':s.itemId?'[data-item="'+s.itemId+'"]':'#tracks'}))};
 $('plan').innerHTML='<h2>Review AI edit plan</h2><p>'+escape(proposal.summary)+'</p><p class="hint">'+escape(proposal.model)+' · '+proposal.steps.length+' actions · no edits applied yet</p>'+proposal.warnings.map(w=>'<p class="hint">'+escape(w)+'</p>').join('')+proposal.steps.map((s,i)=>'<article><b>'+(i+1)+'. '+escape(s.label)+'</b><small>'+escape(s.op.type)+'</small><details><summary>Exact edit parameters</summary><pre>'+escape(JSON.stringify(s.op.arguments,null,2))+'</pre></details></article>').join('');
 $('approve').hidden=!proposal.steps.length;log('AI plan validated. Review and approve to watch it execute.');
 }catch(e){state.plan=null;$('plan').textContent=e.message;throw e;}
 finally{state.running=false;$('stop').hidden=true;$('propose').disabled=false;}
}
async function approvePlan(){const plan=state.plan;if(!plan)throw Error('Create a plan first.');if(state.running||state.busy)return;const latest=await api('GET','/projects/'+plan.projectId);if(latest.revision!==plan.revision||state.project.projectId!==plan.projectId){state.plan=null;$('approve').hidden=true;throw Error('The project changed. Generate a fresh plan before approving.');}pause();state.running=true;state.stop=false;$('approve').hidden=true;$('stop').hidden=false;$('propose').disabled=true;document.body.classList.add('agent-running');let completed=0;try{showPanel('media');for(const step of plan.steps){if(state.stop)break;const target=document.querySelector(step.target)||$('tracks');target.scrollIntoView({block:'nearest',inline:'nearest'});const rect=target.getBoundingClientRect();const cursor=$('agent-cursor');cursor.hidden=false;cursor.style.left=(rect.left+Math.min(30,rect.width/2))+'px';cursor.style.top=(rect.top+Math.min(20,rect.height/2))+'px';target.classList.add('agent-target');await new Promise(r=>setTimeout(r,650));target.classList.remove('agent-target');if(state.stop)break;await commit([step.op],true);completed++;if(step.op.arguments.item){state.selectedId=step.op.arguments.item.id;state.sourceMode=false;state.playhead=seconds(step.op.arguments.item.timelineRange.start);renderTimeline();await showFrame();}if(step.itemId){state.selectedId=step.itemId;const chosen=selection();if(chosen){state.sourceMode=false;state.playhead=seconds(chosen.item.timelineRange.start);fillProperties();renderTimeline();await showFrame();}}log('✓ '+step.label);}toast(state.stop?'Stopped after '+completed+' edits. Applied edits remain; use Undo to reverse them.':'AI edits applied. Press Play to review.');log(state.stop?'Stopped. '+completed+' edits applied.':'Finished. Review the AI edit in the player.');}finally{state.running=false;state.plan=null;$('agent-cursor').hidden=true;$('stop').hidden=true;$('propose').disabled=false;document.body.classList.remove('agent-running');renderTimeline();if(!state.stop)$('fit').click();}}
// Connected same-origin controllers may submit typed proposals, never bypass approval.
window.frameosEditor={propose:async proposal=>{needProject();if(state.running||state.busy)throw Error('Editor is busy.');if(!Array.isArray(proposal.operations)||!proposal.operations.length||proposal.operations.length>200)throw Error('Expected 1–200 operations.');const proposalProject=state.project.projectId,proposalRevision=state.project.revision;const operations=structuredClone(proposal.operations).map(o=>({...o,operationId:uid(),preconditions:o.preconditions||[],provenance:{actorType:'agent',actorId:'studio.connected-agent'}}));await api('POST','/transactions',{projectId:state.project.projectId,baseRevision:state.project.revision,idempotencyKey:'proposal-'+uid(),mode:'validate',operations});if(state.project.projectId!==proposalProject||state.project.revision!==proposalRevision)throw Error('The project changed while validating the proposal.');state.plan={projectId:proposalProject,revision:proposalRevision,steps:operations.map(op=>({label:op.type,target:'#tracks',op}))};showInspector(true);$('plan').replaceChildren();const heading=document.createElement('h2');heading.textContent=proposal.summary||'Connected agent proposal';$('plan').append(heading);for(const op of operations){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent=op.type;const pre=document.createElement('pre');pre.textContent=JSON.stringify(op.arguments,null,2);details.append(summary,pre);$('plan').append(details);}$('approve').hidden=false;},getState:()=>({projectId:state.project?.projectId,revision:state.project?.revision,playhead:state.playhead,selectedItemId:state.selectedId,running:state.running})};
document.querySelectorAll('[data-panel]').forEach(b=>bind(b.id|| (b.id='nav-'+b.dataset.panel),()=>showPanel(b.dataset.panel)));
bind('connection',()=>$('connection-panel').hidden=!$('connection-panel').hidden);bind('connect',connect);$('token').value=state.token;
$('projects').addEventListener('change',guard(()=>openProject($('projects').value)));
bind('new-project',async()=>{if(state.running||state.busy)throw Error('Finish the current action first.');const name=prompt('Project name','Untitled video');if(!name?.trim())return;const p=await api('POST','/projects',{name:name.trim()});const option=document.createElement('option');option.value=p.projectId;option.textContent=name;$('projects').append(option);$('projects').value=p.projectId;await openProject(p.projectId);});
bind('import',()=>{needProject();$('files').accept='video/*,audio/*,image/*';$('files').click();});bind('import-audio',()=>{needProject();$('files').accept='audio/*';$('files').click();});$('files').addEventListener('change',guard(importFiles));$('media-filter').addEventListener('input',renderMedia);
bind('properties-tab',()=>showInspector(false));bind('agent-tab',()=>showInspector(true));bind('play',play);bind('start',()=>seek(0));bind('back',()=>seek(state.playhead-1/fps()));bind('forward',()=>seek(state.playhead+1/fps()));bind('timeline-mode',()=>seek(state.playhead));
bind('split',split);bind('duplicate',async()=>{const {track,item}=needClip();await commit([operation('clip.duplicate',{sequenceId:seq().id,trackId:track.id,newClipId:uid(),timelineStart:time(trackEnd(track))},item.id)]);});bind('delete',async()=>{const x=selection();if(!x)throw Error('Select an item first.');await commit([operation('item.delete',{sequenceId:seq().id,trackId:x.track.id},x.item.id)]);state.selectedId=null;fillProperties();});
for(const action of ['undo','redo'])bind(action,async()=>{needProject();if(state.running||state.busy)throw Error('Stop the assistant before undoing edits.');pause();state.busy=true;try{await api('POST','/projects/'+state.project.projectId+'/'+action,{idempotencyKey:'studio-'+uid()});await reload();}finally{state.busy=false;}});
for(const kind of ['video','audio'])bind('add-'+kind+'-track',async()=>{needProject();await commit([operation('track.add',{sequenceId:seq().id,track:trackObject(kind)})]);});
bind('apply-timing',async()=>{const {item,track}=needClip();const values=['clip-start','source-in','clip-duration'].map(id=>Number($(id).value));if(values.some(v=>!Number.isFinite(v))||values[0]<0)throw Error('Enter valid timing values.');await trimTo(item,track,...values);});
bind('apply-picture',async()=>{const {item,track}=needClip();await commit([operation('item.transform.set',{sequenceId:seq().id,trackId:track.id,transform:{...item.transform,scaleX:Number($('scale').value),scaleY:Number($('scale').value),rotation:Number($('rotation').value),opacity:Number($('opacity').value)}},item.id)]);});
bind('apply-volume',async()=>{const {item,track}=needClip();await commit([operation('audio.gain.set',{sequenceId:seq().id,trackId:track.id,gainDb:Number($('gain').value)},item.id)]);});
bind('marker',async()=>{needProject();const name=prompt('Marker name','Marker');if(name)await commit([operation('marker.add',{sequenceId:seq().id,marker:{id:uid(),name,range:range(state.playhead,1/fps()),metadata:{}}})]);});
bind('add-title',async()=>{needProject();const text=$('title-text').value.trim(),d=Number($('title-duration').value);if(!text||!(d>0))throw Error('Enter title text and a positive duration.');const track=trackObject('video','Titles'),title={id:uid(),type:'title',name:text.slice(0,60),text,timelineRange:range(state.playhead,d),style:{},transform:{},effects:[],enabled:true,locked:false,metadata:{}};await commit([operation('track.add',{sequenceId:seq().id,track}),operation('title.add',{sequenceId:seq().id,trackId:track.id,title})]);state.sourceMode=false;await showFrame();});
$('zoom').addEventListener('input',()=>{state.zoom=Number($('zoom').value);renderTimeline();});bind('fit',()=>{state.zoom=Math.min(100,Math.max(4,($('timeline-scroll').clientWidth-110)/Math.max(10,duration()+2)));$('zoom').value=state.zoom;renderTimeline();});
$('ruler').addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();event.stopPropagation();seek(event.key==='Home'?0:event.key==='End'?duration():state.playhead+(event.key==='ArrowLeft'?-1:1)/fps());}});
document.addEventListener('keydown',guard(async event=>{if(event.target.closest('input,textarea,select,dialog')||state.running||event.repeat)return;if(event.code==='Space'){event.preventDefault();await play();}else if(event.key.toLowerCase()==='s'&&!event.ctrlKey&&!event.metaKey){event.preventDefault();await split();}else if(event.key==='Delete')$('delete').click();else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();$(event.shiftKey?'redo':'undo').click();}else if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();seek(state.playhead+(event.key==='ArrowLeft'?-1:1)/fps());}}));
bind('analyze',async()=>{needProject();const a=state.assets.find(a=>a.id===state.selectedAsset);if(!a||a.kind!=='video')throw Error('Select a video in Your media first.');await analyze(a);showPanel('jobs');await refreshJobs();toast('Gemini analysis started.');});
bind('search',async()=>{needProject();const results=await api('POST','/assets/search',{projectId:state.project.projectId,query:$('search-query').value,mode:'lexical',limit:30});$('search-results').innerHTML=results.map(r=>'<article class="search-result"><button data-result-asset="'+r.assetId+'" data-result-at="'+seconds(r.range?.start)+'">'+escape(r.text||r.labels.join(', '))+'<br><small>'+clock(seconds(r.range?.start))+'</small></button></article>').join('')||'<p class="hint">No indexed matches. Analyze your videos first.</p>';});
$('search-results').addEventListener('click',guard(async e=>{const b=e.target.closest('[data-result-asset]');if(b){await selectMedia(b.dataset.resultAsset);state.sourceTime=Number(b.dataset.resultAt);await showFrame();updateHead();}}));
bind('propose',proposeMontage);bind('approve',approvePlan);bind('stop',()=>{state.stop=true;log('Stop requested; any in-flight edit will finish.');});
bind('export',()=>{needProject();const cap=state.capabilities.find(c=>c.id==='engine.mlt');$('render').disabled=!cap?.available;$('render-status').textContent=cap?.available?'Native renderer available.':'MP4 export unavailable: '+(cap?.reasonUnavailable||'The native render worker is not configured.');$('export-dialog').showModal();});bind('close-export',()=>$('export-dialog').close());
bind('render',async()=>{const j=await api('POST','/renders',{projectId:state.project.projectId,sequenceId:seq().id,outputName:'studio-render.mp4'});$('export-dialog').close();showPanel('jobs');await refreshJobs();toast('Render queued: '+j.id.slice(0,8));});
bind('export-otio',async()=>{const data=await api('POST','/exports/otio',{projectId:state.project.projectId});const url=URL.createObjectURL(new Blob([JSON.stringify(data.document||data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='frameos-timeline.otio.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
setInterval(()=>{if(state.token&&state.project)guard(refreshJobs)();},5000);
// External API edits refresh only when idle, never during scrubbing or a local mutation.
setInterval(guard(async()=>{if(!state.project||state.busy||state.running||state.playing||pointer||document.activeElement?.closest('input,textarea,select'))return;const id=state.project.projectId,revision=state.project.revision;const p=await api('GET','/projects/'+id);if(state.project?.projectId===id&&state.project.revision===revision&&!state.busy&&!state.running&&!pointer&&p.revision!==revision){state.project=p;state.assets=await api('GET','/projects/'+id+'/assets');renderMedia();renderTimeline();fillProperties();await showFrame();toast('Timeline updated by a connected client.');}}),4000);
window.addEventListener('resize',()=>{if(!pointer)renderTimeline();});window.addEventListener('beforeunload',clearMedia);
renderMedia();renderTimeline();if(state.token)guard(connect)();
`;
